insert into public.site_content (page, block_key, original, sort_order, tag) values
  ('index.html', '5', 'We started as three homeschool moms in Phoenix, Arizona with a vision for a Christ-centered homeschool community for our kids and ourselves. We each come from different backgrounds and paths in life, but we’ve been brought together by our love for Jesus Christ and our passion for our families and our kids’ education. We believe that a big part of their education is teaching them to participate in the body of Christ (1 Corinthians 12: 12-31) and the community in which we live (Jeremiah 29:7). We also want to make the most of our different gifts and talents, and recognize our own need as moms to have community and be encouraged by one another.', 5, 'p')
