insert into public.site_content (page, block_key, original, sort_order, tag) values
  ('about-koinonia-faq/index.html', '50', '1.       Apply: Fill out an [Application for Membership](../apply/). You will then be contacted by a member of our leadership team to set up a time to meet in person or over Zoom. We are working to develop a tight-knit community, so we want to get to know you and make sure we are a good fit for each other.', 50, 'p')
